# New entry in inputs.scale_sets
"fcp-lab" = {
  # One FCP Lab per runner pod. The Lab runs in the dind sidecar, so these requests mostly make Karpenter
  # give each pod its own 8 vCPU / 32 GB node from the fcp-lab NodePool (modules/karpenter-node-pool).
  github_config_url = "https://github.com/RhinoHealth/fcp"
  release_name      = "lab-runner-set"
  min_runners       = 0
  max_runners       = 6 # QA has 6 locks today (3 components x 2 clouds); start at the same parallelism
  runner_resources_requests = {
    cpu                 = "6"
    memory              = "24Gi"
    "ephemeral-storage" = "80Gi" # the default EC2NodeClass root volume is 100 GB (eks unit: root_volume_size)
  }
  runner_node_selector = {
    "karpenter.sh/nodepool" = "fcp-lab"
  }
  # New optional field in modules/github-runner-scale-sets/variables.tf, passed to template.spec.tolerations
  runner_tolerations = [
    { key = "example.com/pool", operator = "Equal", value = "fcp-lab", effect = "NoSchedule" }
  ]
}
